mutation BulkEditPeople($personIds: [ID!]!, $values: [FormValueInput!]!, $effectiveFrom: String!, $key: String!) {
    bulkEditPeople(personIds: $personIds, values: $values, effectiveFrom: $effectiveFrom, idempotencyKey: $key) {
      committed rows { personId name outcome changes { key label dated before { ...EntryParts } after { ...EntryParts } } refusal { code message keys } findings { key label level code message review } }
    }
  }
  fragment EntryParts on FormEntry {
    __typename
    ... on TextEntry { key text }
    ... on FlagEntry { key flag }
    ... on ListEntry { key items }
    ... on MoneyEntry { key amountMinor currency }
    ... on SealedEntry { key last4 }
    ... on EmptyEntry { key }
  }
